import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, list]:
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    parsed_rows = list(reader)

    header_index = None
    for index, row in enumerate(parsed_rows):
        normalized = [cell.strip().lstrip("\ufeff").lower() for cell in row]
        if normalized == ["symbol", "alias", "kind"]:
            header_index = index
            break

    if header_index is None:
        for index, row in enumerate(parsed_rows):
            if row and any(cell.strip() for cell in row) and not row[0].lstrip().startswith("#"):
                header_index = index
                break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = [cell.strip().lstrip("\ufeff") for cell in parsed_rows[header_index]]
    rows = [
        [str(cell) for cell in row]
        for row in parsed_rows[header_index + 1 :]
    ]

    width = max([len(columns)] + [len(row) for row in rows])
    while len(columns) < width:
        columns.append(f"extra_{len(columns) + 1}")

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
